update menu_items set is_signature = false, copy_source = 'draft', image_path = '/menu/0011-green-tea.webp', description_en = 'Loose-leaf green tea, steeped gently so it stays clean and grassy rather than bitter.', description_ar = 'شاي أخضر بأوراق كاملة، يُنقع برفق ليبقى نقياً ومنعشاً بلا مرارة.' where sku = '0011';
update menu_items set is_signature = true, copy_source = 'cafe', image_path = '/menu/0016-212-signature.webp', description_en = 'A rich shot of espresso blended with fresh milk, crushed Oreo, and our signature homemade chocolate sauce.', description_ar = 'جرعة غنية من الإسبريسو ممتزجة بالحليب الطازج، وقطع الأوريو المقرمشة، مع صوص الشوكولاتة الخاص المحضّر منزلياً' where sku = '0016';
update menu_items set is_signature = false, copy_source = 'draft', image_path = '/menu/0017-spanish-latte.webp', description_en = 'Espresso with condensed and steamed milk — sweeter and rounder than a standard latte.', description_ar = 'إسبريسو مع الحليب المكثّف والمبخّر — أحلى وأكثر نعومة من اللاتيه المعتاد.' where sku = '0017';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0018-latte.webp', description_en = 'Smooth, rich espresso combined with silky, steamed micro-foam milk for a perfectly balanced and velvety coffee experience.', description_ar = 'إسباديسو غني وناعم ممزوج بالحليب المبخر ذو الرغوة المخملية الحريرية، لتجربة قهوة متوازنة وفاخرة.' where sku = '0018';
update menu_items set is_signature = false, copy_source = 'draft', image_path = '/menu/0019-v60.webp', description_en = 'Coffee brewed by hand through a V60 cone, poured slowly for a clean, aromatic cup. Served black.', description_ar = 'قهوة تُحضَّر يدوياً عبر مصفاة V60، تُسكب ببطء لكوب نقي وعطر. تُقدَّم سادة.' where sku = '0019';
update menu_items set is_signature = true, copy_source = 'draft', image_path = '/menu/0034-the-3-layers.webp', description_en = 'Three layers in one glass — an espresso base, cold milk, and whipped coffee foam — finished with chocolate shavings.', description_ar = 'ثلاث طبقات في كوب واحد — قاعدة إسبريسو، وحليب بارد، ورغوة قهوة مخفوقة — مع رقائق الشوكولاتة.' where sku = '0034';
update menu_items set is_signature = false, copy_source = 'draft', image_path = '/menu/0039-normal-water.webp', description_en = 'Still bottled water, chilled.', description_ar = 'مياه معدنية غير غازية، مبرّدة.' where sku = '0039';
