update menu_items set is_signature = true, copy_source = 'cafe', image_path = '/menu/0049-brownies-chocolate-bomb.webp', description_en = 'Fresh homemade brownie topped with a bowl of creamy vanilla ice cream and warm specialty chocolate sauce to pour over and melt the top.', description_ar = 'براوني طازج ومحضر لدينا يعلوه وعاء من آيس كريم الفانيليا الكريمي مع صوص الشوكولاتة الخاص الدافئ للسكب فوقه وتذويب' where sku = '0049';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0052-the-french-toast.webp', description_en = 'Two pieces of golden, thick-cut artisan brioche soaked in a rich vanilla-cinnamon custard, seared to perfection. Served with salted caramel drizzle, fresh berries, and a side of vanilla ice cream.', description_ar = 'شريحتان سميكتان من خبز البريوش الذهبي الفاخر، مغمورتان في مزيج الكاسترد بالفانيليا والقرفة الغني ومحمصلتان بإتقان. تُقدّم مع لمسة من الكراميل المملح، الفواكه التوتية الطازجة، وجانب من أيس كريم الفانيليا.' where sku = '0052';
update menu_items set is_signature = false, copy_source = 'draft', image_path = '/menu/0056-turkey-sandwich.webp', description_en = 'Sliced turkey with rocket and tomato in a soft-baked roll, pressed until warm.', description_ar = 'شرائح ديك رومي مع الجرجير والطماطم في خبز طري، تُضغط حتى تدفأ.' where sku = '0056';
