update menu_items set is_signature = false, copy_source = 'draft', image_path = '/menu/0059-chocolate-croissant.webp', description_en = 'An all-butter croissant with dark chocolate folded into the layers.', description_ar = 'كرواسون بالزبدة مع الشوكولاتة الداكنة بين طبقاته.' where sku = '0059';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0066-eggs-benedict.webp', description_en = 'Crisp layered potato pavé topped with creamy mashed avocado, two perfectly poached eggs, and rich hollandaise sauce, finished with a pinch of sweet paprika, fresh rocca, and crumbled feta.', description_ar = 'طبقات البطاطس المقرمشة يعلوها مهروس الأفوكادو الكريمي، بيضتان مسلوقتان بدقة، وصوص الهولنديز الغني، مع لمسة من البابريكا الحلوة، الجرجير الطازج، ورشة من جبن الفيتا.' where sku = '0066';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0067-3-mini-sandwiches.webp', description_en = 'Crisp, donut-shaped artisanal falafel crafted from spiced chickpeas and fresh herbs, served over smooth tahini drizzle, garnished with pickled turnips, wild rocket, toasted sesame, and pomegranate seeds.', description_ar = 'فلافل حرفية مقرمشة على شكل دونات محضرة من الحمص المتبل والأعشاب الطازجة، تُقدّم فوق صوص الطحينة الناعمة، وتُزيَّن باللفت المخلل، الجرجير البري، السمسم المحمص، وحبات الرمان.' where sku = '0067';
