update menu_items set is_signature = false, copy_source = 'draft', image_path = '/menu/0075-green-shakshooka.webp', description_en = 'Eggs baked into a green sauce of spinach and herbs, served in the dish they came out of the oven in.', description_ar = 'بيض مخبوز في صلصة خضراء من السبانخ والأعشاب، يُقدَّم في الإناء نفسه الخارج من الفرن.' where sku = '0075';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0076-penne-pasta.webp', description_en = 'Al dente penne folded into an Italian special sauce—a rich combination of three distinct sauces creating a creamy white base with tender pieces of chicken breast. Topped with aged Parmesan, white cheddar, and a pinch of fresh chives and parsley. Served with two slices of toasted bread to enjoy every drop of sauce.', description_ar = 'باستا البيني المطبوخة ببراعة وممزوجة بصلصة إيطالية خاصة,مزيج غني من ثلاثة أنواع مختلفة من الصلصات لابتكار قاعدة بيضاء كريمية مع قطع طرية من صدر الدجاج. تعلوها جُبنة البارميزان المعتقة، الشيدر الأبيض، ورشة البقدونس الطازج. تُقدّم مع شريحتين من الخبز المحمص للاستمتاع بآخر قطرة من الصلصة.' where sku = '0076';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0095-ceremonial-matcha-latte.webp', description_en = 'Japanese ceremonial matcha whisked to perfection and combined with smooth, velvety milk for a vibrant, earthy taste with natural sweetness. Served with a shot of espresso.', description_ar = 'ماتشا يابانية سيريمونيال مخفوقة بإتقان وممزوجة بالحليب المخملي الناعم، لمذاق غني ومنعش وحلاوة طبيعية. يُقدّم مع شوت إسبريسو.' where sku = '0095';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0101-affogato.webp', description_en = 'A scoop of rich, creamy vanilla gelato "drowned" in a freshly pulled shot of hot, double espresso. The perfect balance of hot and cold, sweet and bold.', description_ar = 'كرة من جيلاتو الفانيليا الغنية يسكب عليها "شوت" دافئ من الإسبريسو المزدوج الطازج. التوازن المثالي بين الحرارة والبرودة، والحلاوة والمرارة.' where sku = '0101';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0107-double-espresso.webp', description_en = 'A bold, concentrated double shot of specialty coffee, extracted to highlight rich flavors, natural sweetness, and a velvety crema layer.', description_ar = 'جرعة مضاعفة غنية ومكثفة من القهوة المختصة، تم استخلاصها بعناية لإبراز النكهات الغنية، الحلاوة الطبيعية، وطبقة الكريما المخملية.' where sku = '0107';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0108-english-breakfast-tea.webp', description_en = 'A classic, full-bodied black tea brew delivering a rich, robust malt flavor with a bright golden-amber hue and a refreshing finish.', description_ar = 'الشاي الأحمر الكلاسيكي الفاخر بعبير قوي ونكهة غنية ومكثفة، يتميز بلونه الذهبي الدافئ ولمسته المنعشة.' where sku = '0108';
