update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0110-flat-white.webp', description_en = 'A double shot of rich espresso topped with velvety, micro-foamed steamed milk for a smooth, coffee-forward taste and silky mouthfeel.', description_ar = 'جرعة مضاعفة من الإسبريسو الغني تعلوها رغوة حليب ناعمة ومخملية لمذاق متوازن يبرز نكهة القهوة الغنية وقوام حريري.' where sku = '0110';
update menu_items set is_signature = false, copy_source = 'cafe', image_path = '/menu/0115-non-coffee-matcha.webp', description_en = 'Japanese matcha whisked to perfection and paired with silky, steamed micro-foam milk for a smooth, earthy, and antioxidant-rich beverage.', description_ar = 'ما تشا يابانية فاخرة بدرجة احتفالية مقتناة بعناية، مخفوقة بإتقان وممزوجة مع الحليب المبخر ذو الرغوة المخملية لمشروب ناعم، غني ومضاد للأكسدة.' where sku = '0115';
